To create a FastAPI application with CRUD endpoints for managing a collection of products, follow these steps:

1. Install FastAPI and Uvicorn: FastAPI is the web framework, and Uvicorn is an ASGI server to run the application.

```bash
pip install fastapi uvicorn
```

2. Create a new file named `main.py` and import FastAPI:

```python
from fastapi import FastAPI

app = FastAPI()
```

3. Define a Product model using Pydantic:

```python
from pydantic import BaseModel
from typing import Optional

class Product(BaseModel):
    id: Optional[int] = None
    name: str
    description: str
    price: float
```

4. Implement the CRUD operations using in-memory storage (a Python dictionary):

```python
products = {}

def create_product(product: Product) -> Product:
    product_id = len(products) + 1
    product.id = product_id
    products[product_id] = product
    return product

def get_product(product_id: int) -> Optional[Product]:
    return products.get(product_id)

def update_product(product_id: int, updated_product: Product) -> Optional[Product]:
    if product_id in products:
        products[product_id] = updated_product
        return updated_product
    return None

def delete_product(product_id: int) -> bool:
    if product_id in products:
        del products[product_id]
        return True
    return False
```

5. Create the API endpoints for each CRUD operation:

```python
@app.post("/products/", response_model=Product)
def create_product_endpoint(product: Product):
    return create_product(product)

@app.get("/products/{product_id}", response_model=Optional[Product])
def get_product_endpoint(product_id: int):
    return get_product(product_id)

@app.put("/products/{product_id}", response_model=Optional[Product])
def update_product_endpoint(product_id: int, updated_product: Product):
    return update_product(product_id, updated_product)

@app.delete("/products/{product_id}", response_model=bool)
def delete_product_endpoint(product_id: int):
    return delete_product(product_id)
```

6. The complete `main.py` file should look like this:

```python
from fastapi import FastAPI
from pydantic import BaseModel
from typing import Optional

app = FastAPI()

class Product(BaseModel):
    id: Optional[int] = None
    name: str
    description: str
    price: float

products = {}

def create_product(product: Product) -> Product:
    product_id = len(products) + 1
    product.id = product_id
    products[product_id] = product
    return product

def get_product(product_id: int) -> Optional[Product]:
    return products.get(product_id)

def update_product(product_id: int, updated_product: Product) -> Optional[Product]:
    if product_id in products:
        products[product_id] = updated_product
        return updated_product
    return None

def delete_product(product_id: int) -> bool:
    if product_id in products:
        del products[product_id]
        return True
    return False

@app.post("/products/", response_model=Product)
def create_product_endpoint(product: Product):
    return create_product(product)

@app.get("/products/{product_id}", response_model=Optional[Product])
def get_product_endpoint(product_id: int):
    return get_product(product_id)

@app.put("/products/{product_id}", response_model=Optional[Product])
def update_product_endpoint(product_id: int, updated_product: Product):
    return update_product(product_id, updated_product)

@app.delete("/products/{product_id}", response_model=bool)
def delete_product_endpoint(product_id: int):
    return delete_product(product_id)
```

7. Run the application using Uvicorn:

```bash
uvicorn main:app --reload
```

8. Open your browser and go to `http://127.0.0.1:8000/docs` to see the Swagger/OpenAPI documentation for your API.

Now you have a FastAPI application with CRUD endpoints for managing products, including creating, reading, updating, and deleting products. The API also has built-in Swagger/OpenAPI documentation.

To create a simple REST API using FastAPI, first install the required packages:

```bash
pip install fastapi uvicorn
```

Now create a new Python file (e.g., `main.py`) and add the following code:

```python
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import Dict

app = FastAPI()

class Note(BaseModel):
    title: str
    content: str

notes: Dict[int, Note] = {}

@app.post("/notes/")
def create_note(note: Note):
    note_id = len(notes) + 1
    notes[note_id] = note
    return {"note_id": note_id}

@app.get("/notes/{note_id}")
def read_note(note_id: int):
    if note_id not in notes:
        raise HTTPException(status_code=404, detail="Note not found")
    return notes[note_id]

@app.put("/notes/{note_id}")
def update_note(note_id: int, note: Note):
    if note_id not in notes:
        raise HTTPException(status_code=404, detail="Note not found")
    notes[note_id] = note
    return {"message": "Note updated"}

@app.delete("/notes/{note_id}")
def delete_note(note_id: int):
    if note_id not in notes:
        raise HTTPException(status_code=404, detail="Note not found")
    del notes[note_id]
    return {"message": "Note deleted"}
```

This code defines a simple REST API with endpoints for creating, reading, updating, and deleting notes. The notes are stored in-memory in a dictionary.

To run the application, use the following command:

```bash
uvicorn main:app --reload
```

You can now access the API at http://127.0.0.1:8000 and interact with it using tools like `curl` or Postman. FastAPI also provides an interactive API documentation at http://127.0.0.1:8000/docs.

