#include <iostream>
#include <cmath>

class Shape {
public:
    virtual double area() const = 0;
    virtual double perimeter() const = 0;
};

class Circle : public Shape {
private:
    double radius;

public:
    Circle(double r) : radius(r) {}

    double area() const override {
        return M_PI * radius * radius;
    }

    double perimeter() const override {
        return 2 * M_PI * radius;
    }
};

class Rectangle : public Shape {
private:
    double width, height;

public:
    Rectangle(double w, double h) : width(w), height(h) {}

    double area() const override {
        return width * height;
    }

    double perimeter() const override {
        return 2 * (width + height);
    }
};

class Triangle : public Shape {
private:
    double a, b, c;

public:
    Triangle(double x, double y, double z) : a(x), b(y), c(z) {}

    double area() const override {
        double s = (a + b + c) / 2;
        return sqrt(s * (s - a) * (s - b) * (s - c));
    }

    double perimeter() const override {
        return a + b + c;
    }
};

int main() {
    Circle circle(5);
    Rectangle rectangle(4, 6);
    Triangle triangle(3, 4, 5);

    std::cout << "Circle: Area = " << circle.area() << ", Perimeter = " << circle.perimeter() << std::endl;
    std::cout << "Rectangle: Area = " << rectangle.area() << ", Perimeter = " << rectangle.perimeter() << std::endl;
    std::cout << "Triangle: Area = " << triangle.area() << ", Perimeter = " << triangle.perimeter() << std::endl;

    return 0;
}
```

This code defines a base class `Shape` with two pure virtual methods, `area()` and `perimeter()`. Then, it creates three derived classes: `Circle`, `Rectangle`, and `Triangle`, each of which implements the `area()` and `perimeter()` methods. The main function demonstrates creating instances of these classes and invoking their respective methods to calculate the area and perimeter of each shape.

Here's a Java program that uses multithreading to calculate the factorial of a given integer n:

```java
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

public class FactorialMultithreaded {

    public static void main(String[] args) throws InterruptedException {
        int n = 20; // Change this value to compute the factorial of another number

        System.out.println("Factorial of " + n + " is: " + factorial(n));
    }

    private static BigInteger factorial(int n) throws InterruptedException {
        int numOfThreads = Runtime.getRuntime().availableProcessors();
        List<FactorialThread> threads = new ArrayList<>();

        for (int i = 0; i < numOfThreads; i++) {
            int from = (n / numOfThreads) * i + 1;
            int to = (i == numOfThreads - 1) ? n : (n / numOfThreads) * (i + 1);
            FactorialThread thread = new FactorialThread(from, to);
            threads.add(thread);
            thread.start();
        }

        BigInteger result = BigInteger.ONE;
        for (FactorialThread thread : threads) {
            thread.join();
            result = result.multiply(thread.getResult());
        }

        return result;
    }

    private static class FactorialThread extends Thread {
        private final int from;
        private final int to;
        private BigInteger result;

        public FactorialThread(int from, int to) {
            this.from = from;
            this.to = to;
        }

        @Override
        public void run() {
            result = BigInteger.ONE;
            for (int i = from; i <= to; i++) {
                result = result.multiply(BigInteger.valueOf(i));
            }
        }

        public BigInteger getResult() {
            return result;
        }
    }
}
```

This program calculates the factorial of a given integer `n` using multiple threads. It divides the task among `numOfThreads`, which is determined by the number of available processors in the system.

Each thread calculates a partial factorial for a specific range, and then the main thread combines the results at the end to get the final result.

Here's a C++ program that reads student names and their grades from a text file, sorts them based on their grades (highest to lowest), and writes the sorted list to another text file:

